div.pre:
// remove the 'current patient' tag from a resource
POST /fhir/Patient/example/$meta-delete [Other headers]
<Parameters xmlns="http://hl7.org/fhir"> <parameter> <name value="meta"/> <valueMeta> <tag> <system value="http://example.org/codes/tags"/> <code value="current"/> <display value="Current Inpatient"/> </tag> </valueMeta> </parameter> </Parameters>

// all the tags, profiles, and security labels used on patient resources
HTTP/1.1 200 OK [other headers]
<Parameters xmlns="http://hl7.org/fhir"> <parameter> <name value="return"/> <valueMeta> <profile value="http://hl7.org/fhir/StructureDefinition/daf-patient"/> <tag> <system value="http://example.org/codes/tags"/> <code value="record-lost"/> <display value="Patient File Lost"/> </tag> </valueMeta> </parameter> </Parameters>
